// spec: .qa/e2e/specs/search-prefs.md
// seed: tests/seed.free.geo.spec.ts
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/free-r13.json'), colorScheme: 'dark' });

test.describe('Раунд 13: автосохранение предпочтений (#2911c1)', () => {
  test('Ошибка автосохранения: «השמירה נכשלה. נסו שוב.» @iphone', async ({ page }) => {
    // 1. Оборвать запись в profiles (PATCH) — данные профиля не меняются.
    await page.route('**/rest/v1/profiles*', (r) => (r.request().method() === 'PATCH' ? r.abort() : r.continue()));

    // 2. На `/prefs?from=settings` нажать другую опцию «מי מעניין אותי».
    await page.goto('/prefs?from=settings');
    await expect(page.getByText('מי מעניין אותי')).toBeVisible();
    const radios = page.getByRole('radio');
    await expect(radios).toHaveCount(4);
    // Выбранная опция отличается рамкой «border-white» (без прозрачности) — берём первую невыбранную.
    const idx = await radios.evaluateAll((els) => els.findIndex((e) => !/(^|\s)border-white(\s|$)/.test(e.className)));
    expect(idx, 'есть невыбранная опция «מי מעניין אותי»').toBeGreaterThanOrEqual(0);
    const failed = page.waitForEvent('requestfailed', (r) => r.method() === 'PATCH' && r.url().includes('/rest/v1/profiles'));
    await radios.nth(idx).click();
    await failed;

    // Видно «השמירה נכשלה. נסו שוב.», URL остаётся `/prefs…`.
    await expect(page.getByRole('alert').filter({ hasText: 'השמירה נכשלה. נסו שוב.' })).toBeVisible();
    await expect(page).toHaveURL(/\/prefs/);
  });
});
